                    local function buildReport()
                        local lines = {
                            "========== TANPHAT HUB DEBUG REPORT ==========",
                            "Player: " .. (Players.LocalPlayer and Players.LocalPlayer.Name or "Unknown"),
                            "PlaceId: " .. tostring(game.PlaceId),
                            "JobId: " .. tostring(game.JobId),
                            "Time: " .. os.date("%Y-%m-%d %H:%M:%S"),
                            "Entries: " .. tostring(#entries),
                            "=============================================="
                        }
                        for _, entry in ipairs(entries) do
                            lines[#lines + 1] = string.format(
                                "[%s] [%s] %s",
                                entry.time,
                                entry.kind,
                                entry.message
                            )
                        end
                        return table.concat(lines, "\\n")
                    end

                    local function refresh()
                        if #entries == 0 then
                            logText.Text = "No logs captured yet. Reproduce the issue to collect logs."
                        else
                            local lines = {}
                            for _, entry in ipairs(entries) do
                                lines[#lines + 1] = string.format(
                                    "[%s] [%s] %s",
                                    entry.time,
                                    entry.kind,
                                    entry.message
                                )
                            end
                            logText.Text = table.concat(lines, "\\n")
                        end
                        task.defer(function()
                            local height = math.max(100, logText.TextBounds.Y + 18)
                            logText.Size = UDim2.new(1, -16, 0, height)
                            scroll.CanvasSize = UDim2.new(0, 0, 0, height + 14)
                            scroll.CanvasPosition = Vector2.new(
                                0,
                                math.max(0, scroll.CanvasSize.Y.Offset - scroll.AbsoluteWindowSize.Y)
                            )
                        end)
                    end

                    local function addEntry(message, messageType)
                        local kind = tostring(messageType)
                        local msg = tostring(message)
                        entries[#entries + 1] = {
                            time = os.date("%H:%M:%S"),
                            kind = kind,
                            message = msg
                        }
                        if #entries > maxEntries then
                            table.remove(entries, 1)
                        end
                        refresh()
                    end

                    local connection = LogService.MessageOut:Connect(addEntry)

